const p=$('Plan').first().json;const r=$input.first().json;const b=r.body||{};
if(!Array.isArray(b.keys))throw new Error('Guard fetch failed: '+JSON.stringify(b).slice(0,300));
const cur={};for(const k of b.keys)cur[k.key_id]=k;
const out=[];const skipped=[];
for(const k of p.keys){const c=cur[k.key_id];if(!c){skipped.push({id:k.key_id,why:'not found'});continue;}
 if(c.is_archived){skipped.push({id:k.key_id,why:'archived'});continue;}
 const kn=(c.key_name&&(c.key_name.web||c.key_name.other))||'';if(kn!==k.name){skipped.push({id:k.key_id,why:'name mismatch '+kn});continue;}
 const e={key_id:k.key_id,tags:k.tags,merge_tags:true};
 if(!c.description||!String(c.description).trim())e.description=k.description;else skipped.push({id:k.key_id,why:'description exists, kept'});
 out.push(e);}
if(out.length!==p.keys.length)throw new Error('Guard: '+JSON.stringify(skipped));
return [{json:{body:{keys:out},skipped:skipped,n:out.length}}];

